const rows = items;
const bad = rows.filter(i=>!i.json.email || !/\S+@\S+/.test(i.json.email));
if (bad.length) throw new Error(`Invalid emails: ${bad.length}`);
return rows;

const rows = items[0].json.rows || [];
if (rows.length < 2) return [{json:{send:false, msg:'No data'}}];
const y = Number(rows[0].metricValues[0].value);
const d2 = Number(rows[1].metricValues[0].value);
const change = d2 ? (y-d2)/d2 : 0;
return [{json:{send: Math.abs(change) > 0.25, y, d2, change}}];
